/// <summary>
/// This is an extension class for the VendParameters form METVendParameters datasource.
/// </summary>
[ExtensionOf(formDataFieldStr(VendParameters, METVendParameters, VendorRebatesEnabled))]
final class METVendParameters_METVendParametersDS_Field_Extension
{

}

Method.Source:
/// <summary>
/// Calls on modification of DS field.
/// </summary>
 public void modified()
 {
     next modified();
     FormDataObject formDataObject= any2Object(this) as FormDataObject;
     FormDataSource formDataSource= formDataObject.dataSource();
     METVendParameters metParameters = formDataSource.cursor();

     FormControl rebateAccrualJournalName = formDataSource.formRun().design(1).controlName(formControlStr(VendParameters, METVendorRebatesGroup_RebateAccrualJournalName));
     FormControl holdInvoice              = formDataSource.formRun().design(1).controlName(formControlStr(VendParameters, METVendorRebatesGroup_HoldInvoice));

     // Enable/Disable
     rebateAccrualJournalName.enabled(metParameters.VendorRebatesEnabled);
     holdInvoice.enabled(metParameters.VendorRebatesEnabled);


 }
